mapper.select:
select a.id, a.loan_register_id, a.loan_by, a.loan_count, a.loan_time, a.return_count, a.return_time, a.status, a.remark, a.create_by, a.create_time,
de.name as equipmentName,
de.equ_no as equipmentCode,
d.available_count
from d_loan_return_record a
left join d_loan_register d on a.loan_register_id = d.id
left join d_equipment de on d.equipment_id = de.id

    inner join sys_user u on u.user_name = a.create_by and u.status = '0'
    inner join sys_dept d on u.dept_id = d.dept_id and d.status = '0'


    a.del_flag = '0'
     and a.loan_register_id = #{loanRegisterId}
     and a.loan_by = #{loanBy}
     and a.loan_count = #{loanCount}
     and a.loan_time = #{loanTime}
     and a.return_count = #{returnCount}
     and a.return_time = #{returnTime}
     and a.status = #{status}

        and de.name like concat('%', #{equipmentName}, '%')



${params.dataScope}
order by a.create_time desc
